using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using LighFight.Runtime;
public static class TripoSailorAvatarSetup{
static string Canon(string s)=>NativeRigBones.CanonicalName(s);
static string HumanCanon(string s)=>Canon(s);
public static void Configure(string role){string p="Assets/LighFight/Art/Drafts/TripoSailorPlayable/Source/"+role+"/model.fbx";var i=(ModelImporter)AssetImporter.GetAtPath(p);i.animationType=ModelImporterAnimationType.Generic;i.SaveAndReimport();var model=AssetDatabase.LoadAssetAtPath<GameObject>(p);var bones=model.GetComponentsInChildren<Transform>().ToDictionary(t=>Canon(t.name),t=>t, StringComparer.Ordinal);var h=new List<HumanBone>();foreach(string n in HumanTrait.BoneName){string k=HumanCanon(n);if(bones.TryGetValue(k,out var b))h.Add(new HumanBone{humanName=n,boneName=b.name,limit=new HumanLimit{useDefaultValues=true}});}Debug.Log(role+" mapped="+h.Count+" "+string.Join(",",h.Select(b=>b.humanName+"="+b.boneName)));var d=i.humanDescription;d.human=h.ToArray();var clone=UnityEngine.Object.Instantiate(model);var tool=typeof(UnityEditor.Editor).Assembly.GetType("UnityEditor.AvatarSetupTool");var flags=System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic;tool.GetMethod("SampleBindPose",flags).Invoke(null,new object[]{clone});var wrapper=tool.GetNestedType("BoneWrapper",System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic);var wrappers=Array.CreateInstance(wrapper,HumanTrait.BoneName.Length);var cb=clone.GetComponentsInChildren<Transform>();for(int j=0;j<HumanTrait.BoneName.Length;j++){var name=HumanTrait.BoneName[j];var bone=cb.FirstOrDefault(t=>Canon(t.name)==HumanCanon(name));wrappers.SetValue(Activator.CreateInstance(wrapper,new object[]{name,bone}),j);}tool.GetMethod("MakePoseValid",flags).Invoke(null,new object[]{wrappers});Debug.Log(role+" TPOSE error="+tool.GetMethod("GetPoseError",flags).Invoke(null,new object[]{wrappers}));d.skeleton=clone.GetComponentsInChildren<Transform>().Select(t=>new SkeletonBone{name=t.name,position=t.localPosition,rotation=t.localRotation,scale=t.localScale}).ToArray();UnityEngine.Object.DestroyImmediate(clone);d.upperArmTwist=.5f;d.lowerArmTwist=.5f;d.upperLegTwist=.5f;d.lowerLegTwist=.5f;d.armStretch=.05f;d.legStretch=.05f;d.feetSpacing=0;i.animationType=ModelImporterAnimationType.Human;i.avatarSetup=ModelImporterAvatarSetup.CreateFromThisModel;i.humanDescription=d;i.optimizeGameObjects=false;i.SaveAndReimport();}
}